import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // === Simplest cases ===
  it("empty item list quote → premium 5 G (only processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });
    expect(result).toEqual({ results: [{ premium: 5 }] });
  });

  // === Base premiums for main items ===
  it("quote a plain sword (steel, enchantment 3) → base 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }] }],
    });
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("quote a plain amulet → 60 G base + 6 G first insurance + 5 G fee = 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }] }],
    });
    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("quote a plain staff → 80 G base + 8 G first insurance + 5 G fee = 93 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff", material: "oak", enchantment: 2, cursed: false }] }],
    });
    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("quote a plain potion → 40 G base + 4 G first insurance + 5 G fee = 49 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion", material: "glass", enchantment: 1, cursed: false }] }],
    });
    expect(result).toEqual({ results: [{ premium: 49 }] });
  });

  // === Components ===
  it("quote 1 rune → 25 G base + 2.5 G first insurance (rounded up) + 5 G fee = 33 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 33 }] });
  });
  it("quote 2 runes → 50 G base premium (+ modifiers + fee) = 60 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 60 }] });
  });
  it("quote 3 runes → 60 G base + 6 G first insurance + 5 G fee = 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("quote 4 runes → 100 G base + 10 G first insurance + 5 G fee = 115 G (no block)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it.todo("quote 7 runes → 175 G base premium (3-block + 4 single runes; wait — 60 + 4*25 = 160; per spec 7 runes = 175 G — no block applied on 7)");
  it.todo("quote 2 runes + 1 moonstone → 75 G base premium (no block, different types)");
  it.todo("quote 3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // === Item-level modifier: cursed ===
  it.todo("quote a cursed sword (steel, enchantment 3), newcomer with 0 years → 165 G (100 base + 50 curse + 10 first insurance + 5 fee)");

  // === Item-level modifier: high enchantment ===
  it.todo("quote a sword with enchantment 5 → high-enchantment surcharge applies (30 G)");
  it.todo("quote a sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("quote a cursed sword with enchantment 5 → both surcharges apply");

  // === Policy-level modifiers ===
  it.todo("quote a sword for a customer with exactly 2 years → loyalty discount applies (20% off policy base)");
  it.todo("quote a sword for a customer with 1 year → no loyalty discount");

  // === Modifier scope on multi-item policies ===
  it.todo("policy with cursed sword and plain amulet → base 160 G; curse adds 50 G (of sword only) → 210 G before fee + first insurance");

  // === Rounding in MHPCO's favor ===
  it.todo("premium calculation yielding 197.5 G → 198 G (rounded up)");
  it.todo("payout calculation yielding 350.5 G → 350 G (rounded down)");

  // === Second contract / follow-up ===
  it.todo("customer's second quote → 15% follow-up discount applies to policy base");

  // === First-insurance surcharge is per item ===
  it.todo("long-standing customer's second quote of a cursed sword (enchantment 7) → 160 G total (integration example)");

  // === Newcomer integration example ===
  it.todo("newcomer cursed sword (steel, enchantment 3) integration example → 165 G");

  // === Claims: basic ===
  it.todo("claim on regular sword (steel, enchantment 3), damage 500 G → payout 400 G (500 - 100 deductible)");
  it.todo("claim on rune (250 G insurance), damage 200 G → payout 100 G (200 - 100 deductible)");

  // === Claims: enchantment threshold ===
  it.todo("claim on steel sword enchantment 9, damage 1000 G → payout 400 G (50% then -100 deductible)");
  it.todo("claim on dragon-material sword enchantment 8, damage 1000 G → payout 400 G (high-enchantment wins, then deductible)");
  it.todo("claim on dragon-material sword enchantment 5, damage 800 G → payout 700 G (dragon full, then deductible)");
  it.todo("claim on dragon-material sword enchantment 9, damage 1000 G → payout 400 G (50% wins, then deductible)");

  // === Deductible per damage event ===
  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (100 deductible per item)");

  // === Multiple items of same type ===
  it.todo("policy with two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("dragon attack damages two swords → each entry treated separately with its own deductible");
  it.todo("claim with more sword damages than swords insured → CLI error, non-zero exit");

  // === Cap and cap exhaustion ===
  it.todo("policy with sword and amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword premium modifiers don't affect cap → cap 2000 G");
  it.todo("policy with sword + 3 runes (block) → insurance sum 1750 G");
  it.todo("sword insured (cap 2000), first claim 1500 → payout 1400 G, cap remaining 600 G");
  it.todo("sword insured (cap 2000), second claim 1500 after first → payout 600 G, cap remaining 0 G");

  // === Error cases ===
  it.todo("quote with unknown item type (broomstick) → CLI error");
  it.todo("claim references item not in policy → CLI error");
  it.todo("claim with negative damage amount → CLI error");
});

