const PROCESSING_FEE = 5;
const FIRST_INSURANCE_RATE = 0.1;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

interface Item {
  type: string;
}

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

interface QuoteResult {
  premium: number;
}

interface ScenarioResult {
  results: QuoteResult[];
}

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE = 60;

const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);

const isRuneBlock = (items: Item[]): boolean =>
  items.length === COMPONENT_BLOCK_SIZE && items.every((item) => item.type === "rune");

const itemsBasePremium = (items: Item[]): number =>
  isRuneBlock(items)
    ? COMPONENT_BLOCK_BASE
    : items.reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);

const quotePremium = (step: QuoteStep): number => {
  const base = itemsBasePremium(step.items);
  const firstInsuranceSurcharge = base * FIRST_INSURANCE_RATE;
  return roundUpInMHPCOsFavor(base + firstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
});

