const PROCESSING_FEE = 5;
const FIRST_INSURANCE_RATE = 0.1;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const CURSED_SURCHARGE_RATE = 0.5;

const itemSurcharge = (item: Item): number => {
  const base = BASE_PREMIUM[item.type] ?? 0;
  return item.cursed ? base * CURSED_SURCHARGE_RATE : 0;
};

const itemsSurcharge = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemSurcharge(item), 0);

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

interface QuoteResult {
  premium: number;
}

interface ScenarioResult {
  results: QuoteResult[];
}

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE = 60;

const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);

const groupCountsByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

const typeBasePremium = (type: string, count: number): number => {
  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
    return COMPONENT_BLOCK_BASE;
  }
  return BASE_PREMIUM[type] * count;
};

const itemsBasePremium = (items: Item[]): number =>
  [...groupCountsByType(items)].reduce(
    (total, [type, count]) => total + typeBasePremium(type, count),
    0,
  );

const quotePremium = ({ items }: QuoteStep): number => {
  const base = itemsBasePremium(items);
  const firstInsuranceSurcharge = base * FIRST_INSURANCE_RATE;
  return roundUpInMHPCOsFavor(base + itemsSurcharge(items) + firstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
});

