const itemSurcharge = (item: Item): number => {
  const applicableRates = SURCHARGE_RATES.filter(({ applies }) => applies(item));
  return basePremiumOf(item.type) * sumBy(applicableRates, ({ rate }) => rate);
};

const itemsSurcharge = (items: Item[]): number => sumBy(items, itemSurcharge);

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface Damage {
  itemType: string;
  amount: number;
}

interface ClaimStep {
  op: "claim";
  policy: number;
  incident: {
    cause: string;
    damages: Damage[];
  };
}

type Step = QuoteStep | ClaimStep;

interface Customer {
  yearsWithMHPCO: number;
}

interface Scenario {
  customer: Customer;
  steps: Step[];
}

interface QuoteResult {
  premium: number;
}

interface ClaimResult {
  payout: number;
  remainingCap: number;
}

type StepResult = QuoteResult | ClaimResult;

interface ScenarioResult {
  results: StepResult[];
}

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE = 60;

const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
const roundDownInMHPCOsFavor = (amount: number): number => Math.floor(amount);

const groupCountsByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

const typeBasePremium = (type: string, count: number): number => {
  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
    return COMPONENT_BLOCK_BASE;
  }
  return basePremiumOf(type) * count;
};

const itemsBasePremium = (items: Item[]): number =>
  sumBy([...groupCountsByType(items)], ([type, count]) => typeBasePremium(type, count));

const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;

const LOYALTY_YEARS_THRESHOLD = 2;
const LOYALTY_DISCOUNT_RATE = 0.2;

const isLoyalCustomer = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;

const loyaltyDiscount = (customer: Customer, base: number): number =>
  isLoyalCustomer(customer) ? base * LOYALTY_DISCOUNT_RATE : 0;

const quotePremium = ({ items }: QuoteStep, customer: Customer): number => {
  const base = itemsBasePremium(items);
  const premiumBeforeFee =
    base + itemsSurcharge(items) + firstInsuranceSurcharge(base) - loyaltyDiscount(customer, base);
  return roundUpInMHPCOsFavor(premiumBeforeFee + PROCESSING_FEE);
};

interface Policy {
  items: Item[];
  remainingCap: number;
}

const itemInsuranceValue = (item: Item): number => insuranceValueOf(item.type);

const createPolicy = (step: QuoteStep): Policy => ({
  items: step.items,
  remainingCap: sumBy(step.items, itemInsuranceValue) * CAP_MULTIPLIER,
});

const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
const FULL_REIMBURSEMENT_RATE = 1;

const reimbursementRate = (item: Item): number =>
  isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;

const damagePayout = (damage: Damage, item: Item): number =>
  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);

const findItem = (policy: Policy, itemType: string): Item =>
  policy.items.find((i) => i.type === itemType)!;

const processClaim = (step: ClaimStep, policies: Map<number, Policy>): ClaimResult => {
  const policy = policies.get(step.policy)!;
  const rawPayout = sumBy(step.incident.damages, (d) =>
    damagePayout(d, findItem(policy, d.itemType)),
  );
  const payout = roundDownInMHPCOsFavor(Math.min(rawPayout, policy.remainingCap));
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const policies = new Map<number, Policy>();
  const results: StepResult[] = scenario.steps.map((step, index) => {
    if (step.op === "quote") {
      policies.set(index, createPolicy(step));
      return { premium: quotePremium(step, scenario.customer) };
    }
    return processClaim(step, policies);
  });
  return { results };
};

